SELECT O143191.PRECIO_FARMACIA*1.21, COBOL.BUSCO_STOCK_FINAN(O143191.ITEM_ID,'J'), O143191.CODIGO_BARRA, O143182.LABORATORIO_ID, O143191.DESCRIPCION, O143191.ITEM_ID, O143182.DESCRIPCION, O143191.TROQUEL, O143191.INVENTORY_ITEM_STATUS_CODE, O143191.COD_COBOL, O143191.COD_FARMACIA, O143191.COD_PROVEEDOR, O143191.CATEGORIA, SUM(O143191.MARGEN_DROGUERIA), SUM(O143191.PRECIO_FARMACIA), SUM(O143191.PRECIO), SUM(O143191.PRECIO_DROGUERIA)
FROM DW_SCO.SCO_LABORATORIOS O143182, DW_SCO.SCO_PRODUCTOS_REP O143191
WHERE ( ( O143182.LABORATORIO_ID = ( TO_NUMBER(O143191.PROVEEDOR) ) ) ) AND ( O143191.INVENTORY_ITEM_STATUS_CODE <> 'Inactive' ) AND ( O143182.LABORATORIO_ID IN (( :PROVEEDOR )) )
GROUP BY O143191.PRECIO_FARMACIA*1.21, COBOL.BUSCO_STOCK_FINAN(O143191.ITEM_ID,'J'), O143191.CODIGO_BARRA, O143182.LABORATORIO_ID, O143191.DESCRIPCION, O143191.ITEM_ID, O143182.DESCRIPCION, O143191.TROQUEL, O143191.INVENTORY_ITEM_STATUS_CODE, O143191.COD_COBOL, O143191.COD_FARMACIA, O143191.COD_PROVEEDOR, O143191.CATEGORIA
ORDER BY O143191.DESCRIPCION ASC
